preload() {
  this.load.atlas(
    'hero-walk',
    'assets/hero/hero-walk-sheet.png',
    'assets/hero/hero-walk.json'
  );
  this.load.json('hero-walk-data', 'assets/hero/hero-walk.json');
}

create() {
  const data = this.cache.json.get('hero-walk-data');
  for (const recipe of data.phaser.animations) {
    this.anims.create({ ...recipe, sortFrames: false });
  }
  const firstFrame = data.animations.Walk[0];
  this.add.sprite(160, 120, 'hero-walk', firstFrame)
    .setScale(4)
    .play('Walk');
}

import { AnimatedSprite, Assets } from 'pixi.js';

const sheet = await Assets.load('assets/hero/hero-walk.json');
const data = sheet.data;
const clip = data.pixelwall.clips.find((item) => item.name === 'Walk');
const frames = data.animations.Walk.map((name) => ({
  texture: sheet.textures[name],
  time: data.frames[name].duration,
}));

const sprite = new AnimatedSprite(frames);
sprite.animationSpeed = 1;
sprite.loop = clip.repeat === -1;
sprite.updateAnchor = true;
sprite.position.set(160, 120);
sprite.scale.set(4);
app.stage.addChild(sprite);
sprite.play();

const api = window.pixelwall;
const before = api.inspect();
await api.apply({
  expectedRevision: before.revision,
  label: "Draw badge",
  commands: [{
    type: "draw.ellipse", x: 2, y: 2, width: 12, height: 12,
    color: "#ffb34bff", filled: true
  }]
});
await api.save();
const preview = await api.preview({ scale: 4 });
// preview contains width, height, and a PNG dataUrl.
await api.export({ format: "png", scale: 4 });

